-- ===========================================================================
-- RPCs para TRANSFERIR conferencia/separacao entre requisicoes.
--
-- Cenario real: etiqueta foi conferida na req 683, depois bipada de novo
-- na req 682. Operador quer "mover" a conferencia pra req nova (corrige
-- erro de qual requisicao a etiqueta deveria estar).
--
-- Comportamento: sobrescreve conferida_at/separada_at + por com NOW()
-- e o operador atual. Mantem flag TRUE (continua conferida/separada),
-- mas o evento timeline registra a transferencia.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.bipar_etiqueta_reconferir(
  p_uid       text,
  p_contexto  jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $func$
DECLARE
  v_etiqueta            public.etiquetas_qr%ROWTYPE;
  v_user_id             uuid := auth.uid();
  v_user_nome           text;
  v_loja_id             integer;
  v_referencia_tipo     text;
  v_referencia_id       text;
  v_conferida_anterior  timestamptz;
  v_conferida_por_ant   uuid;
BEGIN
  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada');
  END IF;
  IF v_etiqueta.status = 'descartada' THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
  END IF;

  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo';
  v_referencia_id   := p_contexto->>'referencia_id';
  v_conferida_anterior := v_etiqueta.conferida_at;
  v_conferida_por_ant  := v_etiqueta.conferida_por;

  UPDATE public.etiquetas_qr SET
    foi_conferida = TRUE,
    conferida_at  = NOW(),
    conferida_por = v_user_id,
    loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
  WHERE uid = p_uid
  RETURNING * INTO v_etiqueta;

  SELECT COALESCE(raw_user_meta_data->>'nome', email)
    INTO v_user_nome FROM auth.users WHERE id = v_user_id;

  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
  ) VALUES (
    p_uid, 'reconferida', 'conferencia', v_etiqueta.status, v_etiqueta.status,
    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
    jsonb_build_object(
      'conferida_anterior_at', v_conferida_anterior,
      'conferida_anterior_por', v_conferida_por_ant
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'etiqueta', to_jsonb(v_etiqueta),
    'transferida_de', v_conferida_anterior
  );
END;
$func$;

CREATE OR REPLACE FUNCTION public.bipar_etiqueta_reseparar(
  p_uid       text,
  p_contexto  jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
